package com.storemate.backend.web;
import org.junit.jupiter.api.Test;
import java.time.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.storemate.backend.web.StatutoryPayCalculator.*;

class StatutoryPayCalculatorTest {
 @Test void ordinaryWorkersUseConfirmedNormalDayRatherThanDividingIrregularSixDays(){var week=new Week(LocalDate.of(2026,11,8),160,4,24,10000,true,true,true,true,null,7.0);var s=new Settings(true,false,true,false,1,List.of(),List.of(week),List.of(),true);assertEquals(70000,amount(calculate(month,List.of(),s,now),"WEEKLY"));}
 @Test void statutoryPremiumUsesEachSessionsOwnRate(){var a=work(1,"2026-11-02T22:00:00","2026-11-02T23:00:00");var b=new Work(2,LocalDateTime.parse("2026-11-03T22:00:00"),LocalDateTime.parse("2026-11-03T23:00:00"),12000);var all=List.of(a,b);assertEquals(11000,amount(calculate(month,all,settings(true,false,all,List.of(week(0,false)),List.of()),now),"NIGHT"));}
 @Test void holidayHoursCountTowardSubsequentWeeklyOvertimeWithoutExtraHolidayOvertime(){List<Work> all=new ArrayList<>();for(int i=2;i<=6;i++)all.add(work(i,"2026-11-0"+i+"T09:00:00","2026-11-0"+i+"T17:00:00"));all.add(work(7,"2026-11-07T09:00:00","2026-11-07T11:00:00"));var h=new Holiday(LocalDate.of(2026,11,2),true,0,10000,true);var r=calculate(month,all,settings(true,false,all,List.of(week(0,false)),List.of(h)),now);assertEquals(40000,amount(r,"HOLIDAY"));assertEquals(10000,amount(r,"OVERTIME"));}
 @Test void unknownBusinessSizeAndUnconfirmedWeekCannotSilentlyApply(){var w=work(1,"2026-11-02T22:00:00","2026-11-03T00:00:00");var s=new Settings(null,false,true,false,1,List.of(new ConfirmedWork(1,true,List.of(),null)),List.of(),List.of(),true);assertTrue(calculate(month,List.of(w),s,now).blockers().size()>=2);}
 final YearMonth month=YearMonth.of(2026,11);final LocalDateTime now=LocalDateTime.of(2026,12,1,0,0);
 Work work(long id,String from,String to){return new Work(id,LocalDateTime.parse(from),LocalDateTime.parse(to),10000);}
 Week week(double total,boolean attendance){return new Week(LocalDate.of(2026,11,8),total,4,20,10000,true,attendance,true,true,1200,total>0?Math.min(8,total/20):null);}
 Settings settings(boolean five,boolean part,List<Work> records,List<Week> weeks,List<Holiday> holidays){return new Settings(five,false,true,part,1,records.stream().map(r->new ConfirmedWork(r.id(),true,List.of(),part?240:null)).toList(),weeks,holidays,true);}
 long amount(Result r,String kind){return r.items().stream().filter(i->i.kind().equals(kind)).findFirst().orElseThrow().amount();}
 @Test void fifteenHoursIsInclusiveAndFourWeekAverageUsesContractedHours(){var r=calculate(month,List.of(),settings(true,true,List.of(),List.of(week(60,true)),List.of()),now);assertEquals(30000,amount(r,"WEEKLY"));assertEquals(0,amount(calculate(month,List.of(),settings(true,true,List.of(),List.of(week(59.9,true)),List.of()),now),"WEEKLY"));}
 @Test void absenceDoesNotEarnWeeklyPayAndFiveOrFewerStillEarnsWeekly(){assertEquals(0,amount(calculate(month,List.of(),settings(true,true,List.of(),List.of(week(60,false)),List.of()),now),"WEEKLY"));assertEquals(30000,amount(calculate(month,List.of(),settings(false,true,List.of(),List.of(week(60,true)),List.of()),now),"WEEKLY"));}
 @Test void nightIsOnlyTenPmToSixAmAndUsesSnapshotWage(){var w=work(1,"2026-11-02T21:00:00","2026-11-03T07:00:00");var s=settings(true,false,List.of(w),List.of(week(0,false)),List.of());var r=calculate(month,List.of(w),s,now);assertEquals(40000,amount(r,"NIGHT"));assertEquals(10000,amount(r,"OVERTIME"));assertTrue(r.blockers().isEmpty());}
 @Test void nightAndHolidayAddInsteadOfMultiplying(){var w=work(1,"2026-11-02T22:00:00","2026-11-03T00:00:00");var h=new Holiday(LocalDate.of(2026,11,2),true,8,10000,true);var r=calculate(month,List.of(w),settings(true,false,List.of(w),List.of(week(0,false)),List.of(h)),now);assertEquals(10000,amount(r,"NIGHT"));assertEquals(10000,amount(r,"HOLIDAY"));assertEquals(80000,amount(r,"OTHER"));assertEquals(0,amount(r,"OVERTIME"));}
 @Test void holidayAfterEightHoursAddsOneHundredPercentNotAnotherFifty(){var w=work(1,"2026-11-02T09:00:00","2026-11-02T18:00:00");var r=calculate(month,List.of(w),settings(true,false,List.of(w),List.of(week(0,false)),List.of(new Holiday(LocalDate.of(2026,11,2),true,0,10000,true))),now);assertEquals(50000,amount(r,"HOLIDAY"));assertEquals(0,amount(r,"OVERTIME"));}
 @Test void fiveOrFewerHasNoStatutoryPremiumButVoluntaryAgreementCanApply(){var w=work(1,"2026-11-02T22:00:00","2026-11-03T00:00:00");var s=settings(false,false,List.of(w),List.of(week(0,false)),List.of());assertEquals(0,amount(calculate(month,List.of(w),s,now),"NIGHT"));var agreed=new Settings(false,true,true,false,1,s.work(),s.weeks(),s.holidays(),true);assertEquals(10000,amount(calculate(month,List.of(w),agreed,now),"NIGHT"));}
 @Test void actualBreakIsDeductedFromBaseAndNightAndNeverGuessed(){var w=work(1,"2026-11-02T22:00:00","2026-11-03T02:00:00");var s=new Settings(true,false,true,false,1,List.of(new ConfirmedWork(1,true,List.of(new Pause(LocalDateTime.parse("2026-11-02T23:00:00"),LocalDateTime.parse("2026-11-03T00:00:00"))),null)),List.of(week(0,false)),List.of(),true);var r=calculate(month,List.of(w),s,now);assertEquals(-10000,amount(r,"WAGE_CORRECTION"));assertEquals(15000,amount(r,"NIGHT"));assertEquals(0,amount(r,"OVERTIME"));}
 @Test void overlappingOrOutsideBreaksAreRejected(){var w=work(1,"2026-11-02T09:00:00","2026-11-02T18:00:00");var pause=new Pause(w.from().minusHours(1),w.from());var s=new Settings(true,false,true,false,1,List.of(new ConfirmedWork(1,true,List.of(pause),null)),List.of(week(0,false)),List.of(),true);assertThrows(IllegalArgumentException.class,()->calculate(month,List.of(w),s,now));}
 @Test void shortTimeExtraContractHoursReceiveFiftyPercentEvenBelowEight(){var w=work(1,"2026-11-02T09:00:00","2026-11-02T15:00:00");var r=calculate(month,List.of(w),settings(true,true,List.of(w),List.of(week(60,true)),List.of()),now);assertEquals(10000,amount(r,"OVERTIME"));}
 @Test void weeklyAndDailyOvertimeAreNotCountedTwice(){List<Work> list=new ArrayList<>();for(int i=2;i<=5;i++)list.add(work(i,"2026-11-0"+i+"T09:00:00","2026-11-0"+i+"T17:00:00"));list.add(work(6,"2026-11-06T09:00:00","2026-11-06T19:00:00"));list.add(work(7,"2026-11-07T09:00:00","2026-11-07T11:00:00"));var r=calculate(month,list,settings(true,false,list,List.of(week(0,false)),List.of()),now);assertEquals(20000,amount(r,"OVERTIME"));}
 @Test void missingAttendanceBreaksAndUnknownWageBlockApplication(){var w=new Work(1,LocalDateTime.parse("2026-11-02T09:00:00"),LocalDateTime.parse("2026-11-02T18:00:00"),null);assertFalse(calculate(month,List.of(w),settings(true,false,List.of(),List.of(),List.of()),now).blockers().isEmpty());}
 @Test void contextFromPreviousMonthCountsWeeklyHoursButDoesNotPayTwice(){List<Work> list=new ArrayList<>();for(int i=26;i<=30;i++)list.add(work(i,"2026-10-"+i+"T09:00:00","2026-10-"+i+"T17:00:00"));list.add(work(31,"2026-11-01T09:00:00","2026-11-01T11:00:00"));var wk=new Week(LocalDate.of(2026,11,1),0,4,20,10000,true,false,true,true,null,null);var r=calculate(month,list,settings(true,false,list,List.of(wk),List.of()),now);assertEquals(10000,amount(r,"OVERTIME"));assertEquals(0,amount(r,"NIGHT"));}
}
